pm.test("Status code is 201 - Repository created", function () {
    pm.response.to.have.status(201);
});

pm.test("Response time is less than 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Response has JSON body", function () {
    pm.response.to.be.json;
});

if (pm.response.code === 201) {
    const jsonData = pm.response.json();

    pm.test("Repository name matches", function () {
        pm.expect(jsonData.name).to.eql("Tutorialspoint");
    });

    pm.test("Response contains repository ID", function () {
        pm.expect(jsonData.id).to.be.a("number");
    });

    pm.test("Response contains full_name", function () {
        pm.expect(jsonData).to.have.property("full_name");
    });

    pm.test("Response contains html_url", function () {
        pm.expect(jsonData).to.have.property("html_url");
    });
}

if (pm.response.code === 401) {
    pm.test("401 - Authentication required", function () {
        const jsonData = pm.response.json();
        pm.expect(jsonData.message).to.include("authentication");
    });
}
